}
int wf_front_pack_open_header(wf_front_pack_t*p,const wf_asset_io_t*s,uint8_t*c,size_t cn,uint8_t*h,size_t hn,
 uint32_t n,uint32_t first,uint32_t crc,uint32_t(*clock)(void*),void*u){
