/* Optional raw POST checksum tail. Its exact layout is validated against the
 * already authenticated header on every admission; old compressed bundles
 * retain the normal decoder. Direct reads leave the encoded cache intact. */
static bool raw_catalog(const wf_front_pack_t*p,unsigned first,unsigned count,uint32_t *base){
