#include "wf_tag_prefetch_wait.h"
#define WORK_ADMISSION_TICKS 2400u
#define FIFO_ADMISSION_TICKS 1408u
#define CONTROL_ADMISSION_TICKS 1024u /* Total residual budget, including128 reserve. */
#define DEADLINE_RESERVE_TICKS 128u
#define WORK_OPPORTUNITIES 4u
bool wf_tag_prefetch_wait_service(const wf_tag_prefetch_wait_ops_t*o,wf_tag_prefetch_wait_stats_t*s){
 if(!o||!s||!o->busy||!o->clock||!o->work)return false;
 for(unsigned i=0;i<WORK_OPPORTUNITIES;i++){
  if(!o->busy(o->user))break;
  wf_tag_prefetch_wait_clock_t before,after;o->clock(o->user,&before);
  uint32_t elapsed=(uint16_t)(before.tick-before.stamp);
  if(before.period<12000u||before.period>16000u||elapsed>=before.period||
     before.period-elapsed<CONTROL_ADMISSION_TICKS){s->skipped++;break;}
  /* Selection is pure and charged inside the timestamped opportunity. The
   * selected route is locked: invalidation cannot promote it to FIFO,
   * validation, consumer copy or stop-service under the smaller budget. */
  unsigned route=o->select_route?o->select_route(o->user,before.field):WF_TP_ROUTE_HEAVY;
  if(route>WF_TP_ROUTE_CONSUME)return false;
  uint32_t admission=route==WF_TP_ROUTE_HEAVY?WORK_ADMISSION_TICKS+DEADLINE_RESERVE_TICKS:
   route==WF_TP_ROUTE_FIFO?FIFO_ADMISSION_TICKS+DEADLINE_RESERVE_TICKS:CONTROL_ADMISSION_TICKS;
  if(before.period-elapsed<admission){s->skipped++;break;}
  /* VBlank can clear busy between the first check and the clock read. */
  if(!o->busy(o->user))break;
  uint32_t available=before.period-elapsed;
  if(!s->min_budget||available<s->min_budget)s->min_budget=available;
  unsigned phase=0;bool progress=false;
  bool ok=o->work(o->user,before.field,route,&phase,&progress);o->clock(o->user,&after);s->calls++;
  uint32_t cost=(uint16_t)(after.tick-before.tick),cross=after.field-before.field;
  if(cost>s->max_ticks)s->max_ticks=cost;
  if(phase<WF_TP_WAIT_PHASE_COUNT&&cost>s->max_phase[phase])s->max_phase[phase]=cost;
  if(phase==WF_TP_WAIT_CONTROL){
   s->control_calls++;if(!progress)s->control_no_progress++;
   if(!s->min_control_budget||available<s->min_control_budget)s->min_control_budget=available;
  }
  else if(phase==WF_TP_WAIT_FIFO||phase==WF_TP_WAIT_CONSUME){
   if(phase==WF_TP_WAIT_FIFO)s->fifo_calls++;else s->consume_calls++;
   if(!s->min_payload_budget||available<s->min_payload_budget)s->min_payload_budget=available;
  }
  else if(!s->min_heavy_budget||available<s->min_heavy_budget)s->min_heavy_budget=available;
  s->field_cross+=cross;
  bool missed=cross||cost>available-DEADLINE_RESERVE_TICKS;
  if(missed)s->deadline_cross++;
  if(!ok)return false;
  if(missed||!progress)break;
 }
 return true;
}

